#include <iostream>
#include <sstream>
#include <cstring>
#include <cstdint>

struct StudentRecord {
    char firstName[16];
    char mi;
    char lastName[16];
    int32_t score;
};

void displayRecord(const StudentRecord& s) {
    std::cout << s.firstName << " " << s.mi << " " << s.lastName << " " << s.score << "\n";
}

int main() {
    std::stringstream stream(std::ios::in | std::ios::out | std::ios::binary);

    StudentRecord students[4] = {
        {"Alice", 'M', "Smith", 95},
        {"Bob", 'J', "Jones", 82},
        {"Charlie", 'K', "Brown", 88},
        {"Diana", 'L', "Prince", 99}
    };

    for (const auto& student : students) {
        stream.write(reinterpret_cast<const char*>(&student), sizeof(StudentRecord));
    }

    // Seek to the 3rd record (index 2)
    std::streampos targetPos = 2 * sizeof(StudentRecord);
    stream.seekg(targetPos);
    std::cout << "Current position is " << stream.tellg() << "\n";

    StudentRecord retrieved{};
    stream.read(reinterpret_cast<char*>(&retrieved), sizeof(StudentRecord));
    displayRecord(retrieved);

    std::cout << "Current position is " << stream.tellg() << "\n";
    return 0;
}

#include <iostream>
#include <sstream>
#include <cstring>
#include <cstdint>

struct Student {
    char firstName[16];
    char mi;
    char lastName[16];
    int32_t score;
};

void printStudent(const Student& s) {
    std::cout << s.firstName << " " << s.mi << " " << s.lastName << " " << s.score << "\n";
}

int main() {
    // Simulate a binary file opened with ios::in | ios::out | ios::binary
    std::stringstream stream(std::ios::in | std::ios::out | std::ios::binary);

    Student initialRecords[2] = {
        {"FirstName1", 'A', "LastName1", 10},
        {"FirstName2", 'B', "LastName2", 20}
    };

    for (const auto& rec : initialRecords) {
        stream.write(reinterpret_cast<const char*>(&rec), sizeof(Student));
    }

    // Read the second record (index 1)
    Student s1{};
    stream.seekg(1 * sizeof(Student));
    stream.read(reinterpret_cast<char*>(&s1), sizeof(Student));
    printStudent(s1);

    // Modify and write back
    std::strncpy(s1.lastName, "Yao", sizeof(s1.lastName) - 1);
    stream.seekp(1 * sizeof(Student));
    stream.write(reinterpret_cast<const char*>(&s1), sizeof(Student));

    // Read back to verify
    Student s2{};
    stream.seekg(1 * sizeof(Student));
    stream.read(reinterpret_cast<char*>(&s2), sizeof(Student));
    printStudent(s2);

    return 0;
}
